import { Router } from "express";
import { z } from "zod";
import { findHome, listIncidents } from "../store.ts";

export const incidentsRouter = Router({ mergeParams: true });

const incidentParams = z.object({ homeId: z.string().min(1) });

const incidentQuery = z.object({
  state: z.enum(["open", "resolved"]).optional(),
});

/** GET /api/homes/:homeId/incidents — a home's incidents, newest first. */
incidentsRouter.get("/", (req, res) => {
  const params = incidentParams.safeParse(req.params);
  if (!params.success) {
    res.status(400).json({ error: "invalid_params", detail: params.error.issues });
    return;
  }

  const query = incidentQuery.safeParse(req.query);
  if (!query.success) {
    res.status(400).json({ error: "invalid_query", detail: query.error.issues });
    return;
  }

  const { homeId } = params.data;
  if (!findHome(homeId)) {
    res.status(404).json({ error: "home_not_found", homeId });
    return;
  }

  res.json({ incidents: listIncidents(homeId, query.data.state) });
});

/**
 * The data layer. Reads the fixture once at startup and keeps it in memory, so the service has
 * no database to set up. Writes stay in memory and are lost on restart.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export type Home = {
  id: string;
  name: string;
  address: string;
  timezone: string;
  devices: number;
};

export type IncidentKind = "noise" | "occupancy" | "offline";
export type IncidentStatus = "open" | "resolved";

export type Incident = {
  id: string;
  homeId: string;
  kind: IncidentKind;
  startedAt: string;
  endedAt: string | null;
  peakDb: number | null;
  status: IncidentStatus;
};

type Fixture = { homes: Home[]; incidents: Incident[] };

const dataFile = join(dirname(fileURLToPath(import.meta.url)), "../data/homes.json");
const fixture: Fixture = JSON.parse(readFileSync(dataFile, "utf8"));

const homes = [...fixture.homes];
const incidents = [...fixture.incidents];

export const listHomes = (): Home[] => [...homes];

export const findHome = (id: string): Home | undefined => homes.find((home) => home.id === id);

export function listIncidents(homeId: string, status?: IncidentStatus): Incident[] {
  return incidents
    .filter((incident) => incident.homeId === homeId)
    .filter((incident) => (status ? incident.status === status : true))
    .sort((a, b) => b.startedAt.localeCompare(a.startedAt));
}

export const countOpenIncidents = (homeId: string): number =>
  incidents.filter((incident) => incident.homeId === homeId && incident.status === "open").length;

import express from "express";
import { homesRouter } from "./routes/homes.ts";
import { incidentsRouter } from "./routes/incidents.ts";

export function createApp() {
  const app = express();
  app.use(express.json());

  // The dev web app runs on another port.
  app.use((_req, res, next) => {
    res.setHeader("access-control-allow-origin", "*");
    res.setHeader("access-control-allow-headers", "content-type");
    next();
  });

  app.get("/api/health", (_req, res) => res.json({ ok: true }));
  app.use("/api/homes/:homeId/incidents", incidentsRouter);
  app.use("/api/homes", homesRouter);

  app.use((_req, res) => res.status(404).json({ error: "not_found" }));
  return app;
}

import { Router } from "express";
import { z } from "zod";
import { countOpenIncidents, findHome, listHomes } from "../store.ts";

export const homesRouter = Router();

/** GET /api/homes — every home, with how many incidents are currently open. */
homesRouter.get("/", (_req, res) => {
  res.json({
    homes: listHomes().map((home) => ({ ...home, openIncidents: countOpenIncidents(home.id) })),
  });
});

const homeParams = z.object({ homeId: z.string().min(1) });

/** GET /api/homes/:homeId — one home. */
homesRouter.get("/:homeId", (req, res) => {
  const params = homeParams.safeParse(req.params);
  if (!params.success) {
    res.status(400).json({ error: "invalid_params", detail: params.error.issues });
    return;
  }

  const home = findHome(params.data.homeId);
  if (!home) {
    res.status(404).json({ error: "home_not_found", homeId: params.data.homeId });
    return;
  }
  res.json({ home: { ...home, openIncidents: countOpenIncidents(home.id) } });
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { z } from "zod";
import { createApp } from "../src/app.ts";

/** Start the app on a free port for one test and shut it down afterwards. */
async function withServer<T>(use: (base: string) => Promise<T>): Promise<T> {
  const server = createApp().listen(0);
  await new Promise((resolve) => server.once("listening", resolve));
  const address = server.address();
  if (address === null || typeof address === "string") throw new Error("server did not bind a port");
  try {
    return await use(`http://127.0.0.1:${address.port}`);
  } finally {
    await new Promise((resolve) => server.close(resolve));
  }
}

/** `fetch`, with the body left as `unknown` so each test parses the shape it expects. */
async function get(url: string): Promise<{ status: number; body: unknown }> {
  const res = await fetch(url);
  return { status: res.status, body: await res.json() };
}

const homeSchema = z.object({
  id: z.string(),
  name: z.string(),
  address: z.string(),
  timezone: z.string(),
  devices: z.number(),
  openIncidents: z.number(),
});

const incidentSchema = z.object({
  id: z.string(),
  homeId: z.string(),
  kind: z.enum(["noise", "occupancy", "offline"]),
  startedAt: z.string(),
  endedAt: z.string().nullable(),
  peakDb: z.number().nullable(),
  status: z.enum(["open", "resolved"]),
});

const errorSchema = z.object({ error: z.string() });

test("GET /api/health", async () => {
  await withServer(async (base) => {
    const { status, body } = await get(`${base}/api/health`);
    assert.equal(status, 200);
    assert.deepEqual(body, { ok: true });
  });
});

test("GET /api/homes lists homes with their open incident count", async () => {
  await withServer(async (base) => {
    const { status, body } = await get(`${base}/api/homes`);
    assert.equal(status, 200);
    const { homes } = z.object({ homes: z.array(homeSchema) }).parse(body);
    assert.equal(homes.length, 4);
    assert.equal(homes.find((home) => home.id === "h-01")?.openIncidents, 2);
  });
});

test("GET /api/homes/:homeId returns one home", async () => {
  await withServer(async (base) => {
    const { status, body } = await get(`${base}/api/homes/h-03`);
    assert.equal(status, 200);
    const { home } = z.object({ home: homeSchema }).parse(body);
    assert.equal(home.name, "Nørrebrogade 18");
  });
});

test("GET /api/homes/:homeId is 404 for an unknown home", async () => {
  await withServer(async (base) => {
    const { status, body } = await get(`${base}/api/homes/h-99`);
    assert.equal(status, 404);
    assert.equal(errorSchema.parse(body).error, "home_not_found");
  });
});

test("GET /api/homes/:homeId/incidents lists a home's incidents, newest first", async () => {
  await withServer(async (base) => {
    const { status, body } = await get(`${base}/api/homes/h-01/incidents`);
    assert.equal(status, 200);
    const { incidents } = z.object({ incidents: z.array(incidentSchema) }).parse(body);
    assert.deepEqual(incidents.map((incident) => incident.id), ["i-1001", "i-1002", "i-1003"]);
  });
});

test("GET /api/homes/:homeId/incidents is 404 for an unknown home", async () => {
  await withServer(async (base) => {
    const { status, body } = await get(`${base}/api/homes/h-99/incidents`);
    assert.equal(status, 404);
    assert.equal(errorSchema.parse(body).error, "home_not_found");
  });
});

